{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "od-code-migration",
  "title": "Code migration (default scenario)",
  "title_i18n": {
    "en": "Code migration (default scenario)",
    "zh-CN": "代码迁移（默认场景）",
    "zh-TW": "程式碼遷移（預設場景）",
    "ja": "コードマイグレーション（デフォルトシナリオ）",
    "ko": "코드 마이그레이션 (기본 시나리오)",
    "de": "Code-Migration (Standard-Szenario)",
    "fr": "Migration de code (scénario par défaut)",
    "ru": "Миграция кода (сценарий по умолчанию)",
    "es": "Migración de código (escenario predeterminado)",
    "pt-BR": "Migração de código (cenário padrão)",
    "it": "Migrazione codice (scenario predefinito)",
    "vi": "Di trú mã (kịch bản mặc định)",
    "pl": "Migracja kodu (scenariusz domyślny)",
    "id": "Migrasi kode (skenario default)",
    "nl": "Code-migratie (standaardscenario)",
    "ar": "ترحيل الكود (السيناريو الافتراضي)",
    "tr": "Kod taşıma (varsayılan senaryo)",
    "uk": "Міграція коду (типовий сценарій)"
  },
  "version": "0.1.0",
  "publishedAt": "2026-05-09T14:52:59Z",
  "description": "Default reference pipeline for the code-migration taskKind, with patch-edit ↔ build-test devloop and diff-review handoff.",
  "description_i18n": {
    "en": "Default reference pipeline for the code-migration taskKind, with patch-edit ↔ build-test devloop and diff-review handoff.",
    "zh-CN": "code-migration taskKind 的默认参考流水线，自带 patch-edit ↔ build-test 开发环和 diff-review 交付。",
    "zh-TW": "code-migration taskKind 的預設參考流水線，內建 patch-edit ↔ build-test 開發迴圈與 diff-review 交付。",
    "ja": "code-migration taskKind 用のデフォルトリファレンスパイプライン。patch-edit ↔ build-test の devloop と diff-review ハンドオフを内蔵。",
    "ko": "code-migration taskKind을 위한 기본 레퍼런스 파이프라인. patch-edit ↔ build-test devloop과 diff-review 핸드오프 포함.",
    "de": "Standard-Referenzpipeline für den code-migration taskKind, mit patch-edit ↔ build-test Devloop und diff-review Übergabe.",
    "fr": "Pipeline de référence par défaut pour le taskKind code-migration, avec devloop patch-edit ↔ build-test et handoff diff-review.",
    "ru": "Эталонный конвейер по умолчанию для taskKind code-migration с devloop patch-edit ↔ build-test и передачей diff-review.",
    "es": "Pipeline de referencia por defecto para el taskKind code-migration, con devloop patch-edit ↔ build-test y handoff diff-review.",
    "pt-BR": "Pipeline de referência padrão para o taskKind code-migration, com devloop patch-edit ↔ build-test e handoff diff-review.",
    "it": "Pipeline di riferimento predefinita per il taskKind code-migration, con devloop patch-edit ↔ build-test e handoff diff-review.",
    "vi": "Pipeline tham chiếu mặc định cho taskKind code-migration, kèm devloop patch-edit ↔ build-test và bàn giao diff-review.",
    "pl": "Domyślny pipeline referencyjny dla taskKind code-migration, z devloop patch-edit ↔ build-test i handoff diff-review.",
    "id": "Pipeline referensi default untuk taskKind code-migration, dengan devloop patch-edit ↔ build-test dan handoff diff-review.",
    "nl": "Standaard-referentiepipeline voor de code-migration taskKind, met patch-edit ↔ build-test devloop en diff-review-overdracht.",
    "ar": "خط المعالجة المرجعي الافتراضي لـ taskKind code-migration، مع devloop عبر patch-edit ↔ build-test وتسليم diff-review.",
    "tr": "code-migration taskKind için varsayılan referans pipeline; patch-edit ↔ build-test devloop ve diff-review devri ile.",
    "uk": "Типовий референс-конвеєр для taskKind code-migration з devloop patch-edit ↔ build-test і передачею diff-review."
  },
  "license": "MIT",
  "author": {
    "name": "Open Design",
    "url": "https://github.com/nexu-io"
  },
  "homepage": "https://github.com/nexu-io/open-design/tree/main/plugins/_official/scenarios/od-code-migration",
  "tags": [
    "scenario",
    "first-party",
    "code-migration",
    "phase-7"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "code-migration",
    "scenario": "code-migration",
    "mode": "scenario",
    "pipeline": {
      "stages": [
        {
          "id": "import",
          "atoms": [
            "code-import"
          ]
        },
        {
          "id": "tokens",
          "atoms": [
            "design-extract",
            "token-map"
          ]
        },
        {
          "id": "plan",
          "atoms": [
            "rewrite-plan"
          ]
        },
        {
          "id": "verify",
          "atoms": [
            "patch-edit",
            "build-test"
          ],
          "repeat": true,
          "until": "(build.passing && tests.passing) || iterations>=8"
        },
        {
          "id": "review",
          "atoms": [
            "diff-review"
          ]
        },
        {
          "id": "handoff",
          "atoms": [
            "handoff"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:read",
      "fs:write",
      "subprocess"
    ],
    "useCase": {
      "query": {
        "en": "Migrate {{repoPath}} to {{targetStack}}. Iterate the patch-edit ↔ build-test devloop until the build passes and the existing tests stay green, then surface a diff-review for human accept.",
        "zh-CN": "使用这个插件完成以下任务：Migrate {{repoPath}} to {{targetStack}}. Iterate the patch-edit ↔ build-test devloop until the build passes and the existing tests stay green, then surface a diff-review for human accept."
      },
      "exampleOutputs": [
        {
          "path": "./examples/jquery-to-react.html",
          "title": "jQuery → React 18 migration summary"
        }
      ]
    },
    "inputs": [
      {
        "name": "repoPath",
        "type": "string",
        "required": true,
        "label": "Repository path",
        "placeholder": "./apps/legacy-cart"
      },
      {
        "name": "targetStack",
        "type": "string",
        "required": true,
        "label": "Target stack",
        "placeholder": "React 18 + TypeScript + Vite"
      },
      {
        "name": "buildCommand",
        "type": "string",
        "required": false,
        "label": "Build command",
        "placeholder": "pnpm build"
      },
      {
        "name": "testCommand",
        "type": "string",
        "required": false,
        "label": "Test command",
        "placeholder": "pnpm test"
      }
    ]
  }
}
